entries[290108] = { ["name"] = "Erneuerung", ["text"] = "1.8% von Grundmana 40 Meter Reichweite\nSofort\nErfüllt das Ziel mit Glauben an das Licht, wodurch es sofort um 2 Gesundheit sowie im Verlauf von 15 Sek. um weitere 9 Gesundheit geheilt wird." }
