entries[290110] = { ["name"] = "Segenswort: Züchtigung", ["text"] = "2% von Grundmana 30 Meter Reichweite\nSofort 1 min Abklingzeit\nZüchtigt das Ziel mit (112.5% der Zaubermacht) Heiligschaden und macht es handlungsunfähig . Hält 4 Sek. lang an.\n\nHeilig\nCooldown reduced by 4 sec when you cast Smite." }
entries[290111] = { ["name"] = "Segenswort: Epiphanie", ["text"] = "4% von Grundmana 40 Meter Reichweite\nSofort 1 min Abklingzeit\nLässt ein Wunder geschehen und heilt einen Verbündeten um 37 Gesundheit." }
entries[290112] = { ["name"] = "Verbindende Heilung", ["text"] = "2.9% von Grundmana 40 Meter Reichweite\nWirken in 1.5 sek.\nHeilt Euch, Euer Ziel und ein weiteres verbündetes Ziel innerhalb von 20 Metern um 5 Gesundheit.\n\nVerringert die verbleibende Abklingzeit von 'Segenswort: Epiphanie' und 'Segenswort: Heiligung' um 0 Sek." }
