entries[290438] = { ["name"] = "Verhexen", ["text"] = "30 Meter Reichweite\nWirken in 1.7 sek. 30 sek. Abklingzeit\nVerwandelt den Gegner für 8 Sek. in einen Frosch. Während das Ziel verhext ist, ist es handlungsunfähig und kann weder angreifen noch Zauber wirken. Schaden kann den Effekt beenden. Maximal 1 Ziel. Kann nur auf Humanoide und Wildtiere angewandt werden." }
