entries[290471] = { ["name"] = "Blutwurst aus Boralus", ["text"] = "Wirken in 2 sek.\nReagenzien:\nDickes Paleosteak (5), Fusaka (3), Aromatisches Fischöl (2), Blutzelle (5)\nBereitet Blutwurst aus Boralus zu.\nBerufsausbilder:\nKochkunst von Battle for Azeroth (10)\nKosten:\n30\n\n(5)\nBenutzen: Stellt im Verlauf von 20 Sek. 38462 Gesundheit und 23077 Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und ein Wert wird 1 Stunde lang um 39 erhöht.\n45" }
entries[290472] = { ["name"] = "Blutwurst aus Boralus", ["text"] = "Wirken in 2 sek.\nReagenzien:\nDickes Paleosteak (5), Fusaka (3), Aromatisches Fischöl (2), Blutzelle (5)\nStellt bei jeder Zubereitung zusätzliche Blutwurst aus Bolarus her.\nVerkäufer:\nWeltverkäufer\nTortollanische Sucher - Ehrfürchtig\nKosten:\n1900\n\n(7)\nBenutzen: Stellt im Verlauf von 20 Sek. 38462 Gesundheit und 23077 Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und ein Wert wird 1 Stunde lang um 39 erhöht.\n45" }
entries[290473] = { ["name"] = "Blutwurst aus Boralus", ["text"] = "Wirken in 2 sek.\nReagenzien:\nDickes Paleosteak (5), Fusaka (3), Aromatisches Fischöl (2), Blutzelle (5)\nIhr verschwendet nichts von Euren Zutaten und stellt so bei jeder Zubereitung viel mehr Blutwurst aus Bolarus her.\nBeute von:\nVorräte der tortollanischen Sucher\n\n(10)\nBenutzen: Stellt im Verlauf von 20 Sek. 38462 Gesundheit und 23077 Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und ein Wert wird 1 Stunde lang um 39 erhöht.\n45" }
