entries[290491] = { ["name"] = "Schild der Rechtschaffenen", ["text"] = "Nahkampfreichweite\nSofort 9 sek. Abklingzeit\nVerpasst Gegnern vor Euch einen heftigen Schlag mit Eurem Schild, der 2 Heiligschaden verursacht und Eure Rüstung für 4.5 Sek. um 125% erhöht." }
