entries[290494] = { ["name"] = "Schild des Rächers", ["text"] = "35 Meter Reichweite\nSofort 14 sek. Abklingzeit\nSchleudert Euren Schild auf ein gegnerisches Ziel und fügt ihm 3 Heiligschaden zu. Der Schild springt anschließend auf 2 weitere Gegner in der Nähe über.\n\nErhöht außerdem den Effekt Eures nächsten Einsatzes von 'Schild der Rechtschaffenen' um 20%." }
entries[290495] = { ["name"] = "Heldenmut des Rächers", ["text"] = "Unbegrenzte Reichweite\nSofort\nSchleudert Euren Schild auf den Gegner und fügt ihm (75.3523% der Angriffskraft) Heiligschaden zu. Unterbricht das Ziel und bringt es, falls es kein Spielercharakter ist, 3 Sek. lang zum Schweigen. Springt anschließend auf 2 weitere Gegner in der Nähe über.\n\nSchutz\nShields you for 8 sec, absorbing 60% as much damage as it dealt.\n\nSchutz\nDeals ((8.04205% der Angriffskraft)) additional damage to all enemies within 5 yds of each target hit." }
