entries[290540] = { ["name"] = "Hand des Todes", ["text"] = "30 Meter Reichweite\nSofort 5 sek. Abklingzeit\nGreift mit nekrotischen Ranken zu, die 1 Schattenschaden verursachen und Euer Ziel mit Blutseuche infizieren.\n\nBlutseuche\nEine schattenhafte Krankheit, die dem Ziel im Verlauf von 24 Sek. 4 Gesundheit entzieht." }
entries[290541] = { ["name"] = "Markzerfetzer", ["text"] = "Nahkampfreichweite\nSofort 6 sek. Abklingzeit\nBenötigt Nahkampfwaffe\nZerschmettert das Ziel, fügt ihm 3 körperlichen Schaden zu und erzeugt 3 Aufladungen von 'Knochenschild'.\n\nKnochenschild\nUmgibt Euch mit einer Barriere aus wirbelnden Knochen, die Eure Rüstung um (- 40 * Stärke / 100) und Euer Tempo um 10% erhöht. Jeder Nahkampfangriff gegen Euch verbraucht eine Aufladung. Hält 30 Sek. lang an oder bis alle Aufladungen verbraucht wurden." }
