entries[290640] = { ["name"] = "Meisterlicher Gestaltwandler", ["text"] = "Sofort\nBenötigt Katzengestalt\nEure Fähigkeiten werden abhängig von Eurer aktuellen Gestalt verstärkt und gewähren einen zusätzlichen Effekt.\n\n'Zorn', 'Sternenfeuer' und 'Sternensog' verursachen 30% mehr Schaden und erzeugen 30625 Mana.\n\nBärengestalt\n'Eisenfell' gewährt 30% mehr Rüstung und erzeugt 43750 Mana.\n\nKatzengestalt\n'Zerfetzen', 'Wilder Biss' und 'Zerfleddern' verursachen 60% mehr Schaden und erzeugen 175000 Mana, wenn Ihr beim Einsatz 5 Combopunkte habt." }
